def safe_makedirs(fdir):
    """
    Make an arbitrary directory.  This is safe to call for Python 2 users.

    :param fdir: Directory path to make.
    :return:
    """
    if os.path.isdir(fdir):
        pass
        # print 'dir already exists: %s' % str(dir)
    else:
