def line3d(
    x, y, z, label=None, color=None, width=None, dash=None, opacity=None, mode='lines+markers'
):
    """Create a 3d line chart."""
    x = np.atleast_1d(x)
    y = np.atleast_1d(y)
    z = np.atleast_1d(z)
    assert x.shape == y.shape
    assert y.shape == z.shape
    lineattr = {}
    if color:
        lineattr['color'] = color
    if width:
        lineattr['width'] = width
    if dash:
        lineattr['dash'] = dash
    if y.ndim == 2:
        if not hasattr(label, '__iter__'):
            if label is None:
                label = _labels()
            else:
                label = _labels(label)
        data = [
            go.Scatter3d(x=xx, y=yy, z=zz, name=ll, line=lineattr, mode=mode, opacity=opacity)
            for ll, xx, yy, zz in zip(label, x.T, y.T, z.T)
        ]
    else:
        data = [go.Scatter3d(x=x, y=y, z=z, name=label, line=lineattr, mode=mode, opacity=opacity)]
    return Chart(data=data)

def bar(x=None, y=None, label=None, mode='group', yaxis=1, opacity=None):
    """Create a bar chart.

    Parameters
    ----------
    x : array-like, optional
    y : TODO, optional
    label : TODO, optional
    mode : 'group' or 'stack', default 'group'
    opacity : TODO, optional

    Returns
    -------
    Chart
        A Chart with bar graph data.

    """
    assert x is not None or y is not None, "x or y must be something"
    yn = 'y' + str(yaxis)
    if y is None:
        y = x
        x = None
    if x is None:
        x = np.arange(len(y))
    else:
        x = _try_pydatetime(x)
    x = np.atleast_1d(x)
    y = np.atleast_1d(y)
    if y.ndim == 2:
        if not hasattr(label, '__iter__'):
            if label is None:
                label = _labels()
            else:
                label = _labels(label)
        data = [go.Bar(x=x, y=yy, name=ll, yaxis=yn, opacity=opacity) for ll, yy in zip(label, y.T)]
    else:
        data = [go.Bar(x=x, y=y, name=label, yaxis=yn, opacity=opacity)]
    if yaxis == 1:
        return Chart(data=data, layout={'barmode': mode})

    return Chart(data=data, layout={'barmode': mode, 'yaxis' + str(yaxis): dict(overlaying='y')})

def RegisterAt(cls, *args, **kwargs):
        """
**RegisterAt**

    RegisterAt(n, f, library_path, alias=None, original_name=None, doc=None, wrapped=None, explanation="", method_type=utils.identity, explain=True, _return_type=None)

Most of the time you don't want to register an method as such, that is, you don't care about the `self` builder object, instead you want to register a function that transforms the value being piped down the DSL. For this you can use `RegisterAt` so e.g.

    def some_fun(obj, arg1, arg2):
        # code

    @MyBuilder.RegisterMethod("my_lib.")
    def some_fun_wrapper(self, arg1, arg2):
        return self.ThenAt(1, some_fun, arg1, arg2)

can be written directly as

    @MyBuilder.RegisterAt(1, "my_lib.")
    def some_fun(obj, arg1, arg2):
        # code

For this case you can just use `Register` which is a shortcut for `RegisterAt(1, ...)`

    @MyBuilder.Register("my_lib.")
    def some_fun(obj, arg1, arg2):
        # code

**Also See**

* `phi.builder.Builder.RegisterMethod`
        """
        unpack_error = True

        try:
            n, f, library_path = args
            unpack_error = False
            cls._RegisterAt(n, f, library_path, **kwargs)

        except:
            if not unpack_error:
                raise

            def register_decorator(f):
                n, library_path = args
                cls._RegisterAt(n, f, library_path, **kwargs)

                return f
            return register_decorator

def Then0(self, f, *args, **kwargs):
        """
`Then0(f, ...)` is equivalent to `ThenAt(0, f, ...)`. Checkout `phi.builder.Builder.ThenAt` for more information.
        """
        return self.ThenAt(0, f, *args, **kwargs)

def Then(self, f, *args, **kwargs):
        """
`Then(f, ...)` is equivalent to `ThenAt(1, f, ...)`. Checkout `phi.builder.Builder.ThenAt` for more information.
        """
        return self.ThenAt(1, f, *args, **kwargs)

def Then2(self, f, arg1, *args, **kwargs):
        """
`Then2(f, ...)` is equivalent to `ThenAt(2, f, ...)`. Checkout `phi.builder.Builder.ThenAt` for more information.
        """
        args = (arg1,) + args
        return self.ThenAt(2, f, *args, **kwargs)

def Then3(self, f, arg1, arg2, *args, **kwargs):
        """
`Then3(f, ...)` is equivalent to `ThenAt(3, f, ...)`. Checkout `phi.builder.Builder.ThenAt` for more information.
        """
        args = (arg1, arg2) + args
        return self.ThenAt(3, f, *args, **kwargs)

def Then4(self, f, arg1, arg2, arg3, *args, **kwargs):
        """
`Then4(f, ...)` is equivalent to `ThenAt(4, f, ...)`. Checkout `phi.builder.Builder.ThenAt` for more information.
        """
        args = (arg1, arg2, arg3) + args
        return self.ThenAt(4, f, *args, **kwargs)

def Then5(self, f, arg1, arg2, arg3, arg4, *args, **kwargs):
        """
`Then5(f, ...)` is equivalent to `ThenAt(5, f, ...)`. Checkout `phi.builder.Builder.ThenAt` for more information.
        """
        args = (arg1, arg2, arg3, arg4) + args
        return self.ThenAt(5, f, *args, **kwargs)

def ReadList(self, *branches, **kwargs):
        """
Same as `phi.dsl.Expression.List` but any string argument `x` is translated to `Read(x)`.
        """
        branches = map(lambda x: E.Read(x) if isinstance(x, str) else x, branches)

        return self.List(*branches, **kwargs)

def Write(self, *state_args, **state_dict):
        """See `phi.dsl.Expression.Read`"""
        if len(state_dict) + len(state_args) < 1:
            raise Exception("Please include at-least 1 state variable, got {0} and {1}".format(state_args, state_dict))

        if len(state_dict) > 1:
            raise Exception("Please include at-most 1 keyword argument expression, got {0}".format(state_dict))

        if len(state_dict) > 0:
            state_key = next(iter(state_dict.keys()))
            write_expr = state_dict[state_key]

            state_args += (state_key,)

            expr = self >> write_expr

        else:
            expr = self



        def g(x, state):
            update = { key: x for key in state_args }
            state = utils.merge(state, update)

            #side effect for convenience
            _StateContextManager.REFS.update(state)

            return x, state


        return expr.__then__(g)

def contains(string, substring):
    """
    Returns true if the sequence of graphemes in substring is also present in string.

    This differs from the normal python `in` operator, since the python operator will return
    true if the sequence of codepoints are withing the other string without considering
    grapheme boundaries.

    Performance notes: Very fast if `substring not in string`, since that also means that
    the same graphemes can not be in the two strings. Otherwise this function has linear time
    complexity in relation to the string length. It will traverse the sequence of graphemes until
    a match is found, so it will generally perform better for grapheme sequences that match early.

    >>> "🇸🇪" in "🇪🇸🇪🇪"
    True
    >>> grapheme.contains("🇪🇸🇪🇪", "🇸🇪")
    False
    """
    if substring not in string:
        return False

    substr_graphemes = list(graphemes(substring))

    if len(substr_graphemes) == 0:
        return True
    elif len(substr_graphemes) == 1:
        return substr_graphemes[0] in graphemes(string)
    else:
        str_iter = graphemes(string)
        str_sub_part = []
        for _ in range(len(substr_graphemes)):
            try:
                str_sub_part.append(next(str_iter))
            except StopIteration:
                return False

        for g in str_iter:
            if str_sub_part == substr_graphemes:
                return True

            str_sub_part.append(g)
            str_sub_part.pop(0)
        return str_sub_part == substr_graphemes

def readB1logfile(filename):
    """Read B1 logfile (*.log)

    Inputs:
        filename: the file name

    Output: A dictionary.
    """
    dic = dict()
    # try to open. If this fails, an exception is raised
    with open(filename, 'rt', encoding='utf-8') as f:
        for l in f:
            l = l.strip()
            if l[0] in '#!%\'':
                continue  # treat this line as a comment
            try:
                # find the first tuple in _logfile_data where the first element of the
                # tuple is the starting of the line.
                ld = [ld_ for ld_ in _logfile_data if l.split(
                    ':', 1)[0].strip() == ld_[0]][0]
            except IndexError:
                # line is not recognized. We can still try to load it: find the first
                # semicolon. If found, the part of the line before it is stripped
                # from whitespaces and will be the key. The part after it is stripped
                # from whitespaces and parsed with misc.parse_number(). If no
                if ':' in l:
                    key, val = [x.strip() for x in l.split(':', 1)]
                    val = misc.parse_number(val)
                    dic[key] = val
                    try:
                        # fix the character encoding in files written by a
                        # previous version of this software.
                        dic[key] = dic[key].encode('latin2').decode('utf-8')
                    except (UnicodeDecodeError, UnicodeEncodeError, AttributeError):
                        pass
                else:
                    dic[l.strip()] = True
                continue
            try:
                reader = ld[3]
            except IndexError:
                reader = str
            rhs = l.split(':', 1)[1].strip()
            try:
                vals = reader(rhs)
            except ValueError:
                if rhs.lower() == 'none':
                    vals = None
                else:
                    raise
            if isinstance(ld[1], tuple):
                # more than one field names. The reader function should return a
                # tuple here, a value for each field.
                if len(vals) != len(ld[1]):
                    raise ValueError(
                        'Cannot read %d values from line %s in file!' % (len(ld[1]), l))
                dic.update(dict(list(zip(ld[1], vals))))
            else:
                dic[ld[1]] = vals
    dic['__Origin__'] = 'B1 log'
    dic['__particle__'] = 'photon'
    return dic

def _readedf_extractline(left, right):
    """Helper function to interpret lines in an EDF file header.
    """
    functions = [int, float, lambda l:float(l.split(None, 1)[0]),
                 lambda l:int(l.split(None, 1)[0]),
                 dateutil.parser.parse, lambda x:str(x)]
    for f in functions:
        try:
            right = f(right)
            break
        except ValueError:
            continue
    return right

def readBerSANS(filename):
    """Read a header from a SANS file (produced usually by BerSANS)"""
    hed = {'Comment': ''}
    translate = {'Lambda': 'Wavelength',
                 'Title': 'Owner',
                 'SampleName': 'Title',
                 'BeamcenterX': 'BeamPosY',
                 'BeamcenterY': 'BeamPosX',
                 'Time': 'MeasTime',
                 'TotalTime': 'MeasTime',
                 'Moni1': 'Monitor',
                 'Moni2': 'Monitor',
                 'Moni': 'Monitor',
                 'Transmission': 'Transm',
                 }
    with open(filename, 'rt') as f:
        comment_next = False
        for l in f:
            l = l.strip()
            if comment_next:
                hed['Comment'] = hed['Comment'] + '\n' + l
                comment_next = False
            elif l.startswith('%Counts'):
                break
            elif l.startswith('%Comment'):
                comment_next = True
            elif l.startswith('%'):
                continue
            elif l.split('=', 1)[0] in translate:
                hed[translate[l.split('=', 1)[0]]] = misc.parse_number(
                    l.split('=', 1)[1])
            else:
                try:
                    hed[l.split('=', 1)[0]] = misc.parse_number(
                        l.split('=', 1)[1])
                except IndexError:
                    print(l.split('=', 1))
    if 'FileName' in hed:
        m = re.match('D(\d+)\.(\d+)', hed['FileName'])
        if m is not None:
            hed['FSN'] = int(m.groups()[0])
            hed['suffix'] = int(m.groups()[1])
    if 'FileDate' in hed:
        hed['Date'] = dateutil.parser.parse(hed['FileDate'])
    if 'FileTime' in hed:
        hed['Date'] = datetime.datetime.combine(
            hed['Date'].date(), dateutil.parser.parse(hed['FileTime']).time())
    hed['__Origin__'] = 'BerSANS'
    if 'SD' in hed:
        hed['Dist'] = hed['SD'] * 1000
    if hed['Comment'].startswith('\n'):
        hed['Comment'] = hed['Comment'][1:]
    hed['__particle__'] = 'neutron'
    hed['Wavelength'] *= 10  # convert from nanometres to Angstroems
    return hed

def readspecscan(f, number=None):
    """Read the next spec scan in the file, which starts at the current position."""
    scan = None
    scannumber = None
    while True:
        l = f.readline()
        if l.startswith('#S'):
            scannumber = int(l[2:].split()[0])
            if not ((number is None) or (number == scannumber)):
                # break the loop, will skip to the next empty line after this
                # loop
                break
            if scan is None:
                scan = {}
            scan['number'] = scannumber
            scan['command'] = l[2:].split(None, 1)[1].strip()
            scan['data'] = []
        elif l.startswith('#C'):
            scan['comment'] = l[2:].strip()
        elif l.startswith('#D'):
            scan['datestring'] = l[2:].strip()
        elif l.startswith('#T'):
            scan['countingtime'] = float(l[2:].split()[0])
            scan['scantimeunits'] = l[2:].split()[1].strip()
        elif l.startswith('#M'):
            scan['countingcounts'] = float(l[2:].split()[0])
        elif l.startswith('#G'):
            if 'G' not in scan:
                scan['G'] = []
            scan['G'].extend([float(x) for x in l.split()[1:]])
        elif l.startswith('#P'):
            if 'positions' not in scan:
                scan['positions'] = []
            scan['positions'].extend([float(x) for x in l.split()[1:]])
        elif l.startswith('#Q'):
            pass
        elif l.startswith('#N'):
            n = [float(x) for x in l[2:].strip().split()]
            if len(n) == 1:
                scan['N'] = n[0]
            else:
                scan['N'] = n
        elif l.startswith('#L'):
            scan['Columns'] = [x.strip() for x in l[3:].split('  ')]
        elif not l:
            # end of file
            if scan is None:
                raise SpecFileEOF
            else:
                break
        elif not l.strip():
            break  # empty line, end of scan in file.
        elif l.startswith('#'):
            # ignore other lines starting with a hashmark.
            continue
        else:
            scan['data'].append(tuple(float(x) for x in l.split()))
    while l.strip():
        l = f.readline()
    if scan is not None:
        scan['data'] = np.array(
            scan['data'], dtype=list(zip(scan['Columns'], itertools.repeat(np.float))))
        return scan
    else:
        return scannumber

def readspec(filename, read_scan=None):
    """Open a SPEC file and read its content

    Inputs:

        filename: string
            the file to open

        read_scan: None, 'all' or integer
            the index of scan to be read from the file. If None, no scan should be read. If
            'all', all scans should be read. If a number, just the scan with that number
            should be read.

    Output:
        the data in the spec file in a dict.
    """
    with open(filename, 'rt') as f:
        sf = {'motors': [], 'maxscannumber': 0}
        sf['originalfilename'] = filename
        lastscannumber = None
        while True:
            l = f.readline()
            if l.startswith('#F'):
                sf['filename'] = l[2:].strip()
            elif l.startswith('#E'):
                sf['epoch'] = int(l[2:].strip())
                sf['datetime'] = datetime.datetime.fromtimestamp(sf['epoch'])
            elif l.startswith('#D'):
                sf['datestring'] = l[2:].strip()
            elif l.startswith('#C'):
                sf['comment'] = l[2:].strip()
            elif l.startswith('#O'):
                try:
                    l = l.split(None, 1)[1]
                except IndexError:
                    continue
                if 'motors' not in list(sf.keys()):
                    sf['motors'] = []
                sf['motors'].extend([x.strip() for x in l.split('  ')])
            elif not l.strip():
                # empty line, signifies the end of the header part. The next
                # line will be a scan.
                break
        sf['scans'] = {}
        if read_scan is not None:
            if read_scan == 'all':
                nr = None
            else:
                nr = read_scan
            try:
                while True:
                    s = readspecscan(f, nr)
                    if isinstance(s, dict):
                        sf['scans'][s['number']] = s
                        if nr is not None:
                            break
                        sf['maxscannumber'] = max(
                            sf['maxscannumber'], s['number'])
                    elif s is not None:
                        sf['maxscannumber'] = max(sf['maxscannumber'], s)
            except SpecFileEOF:
                pass
        else:
            while True:
                l = f.readline()
                if not l:
                    break
                if l.startswith('#S'):
                    n = int(l[2:].split()[0])
                    sf['maxscannumber'] = max(sf['maxscannumber'], n)
        for n in sf['scans']:
            s = sf['scans'][n]
            s['motors'] = sf['motors']
            if 'comment' not in s:
                s['comment'] = sf['comment']
            if 'positions' not in s:
                s['positions'] = [None] * len(sf['motors'])
    return sf

def maskname(self) -> Optional[str]:
        """Name of the mask matrix file."""
        try:
            maskid = self._data['maskname']
            if not maskid.endswith('.mat'):
                maskid = maskid + '.mat'
            return maskid
        except KeyError:
            return None

def beamcenterx(self) -> ErrorValue:
        """X (column) coordinate of the beam center, pixel units, 0-based."""
        try:
            return ErrorValue(self._data['geometry']['beamposy'],
                              self._data['geometry']['beamposy.err'])
        except KeyError:
            return ErrorValue(self._data['geometry']['beamposy'],
                              0.0)

def beamcentery(self) -> ErrorValue:
        """Y (row) coordinate of the beam center, pixel units, 0-based."""
        try:
            return ErrorValue(self._data['geometry']['beamposx'],
                              self._data['geometry']['beamposx.err'])
        except KeyError:
            return ErrorValue(self._data['geometry']['beamposx'],
                              0.0)

